import os
BASE = r'D:\Seed'
for p in ['src/evaluator/runEvaluation.ts']:
    f=os.path.join(BASE,p)
    if os.path.exists(f): os.remove(f); print(f'REMOVED {p}')

F={}
F['src/evaluator/WorldEvaluator.ts'] = "// WorldEvaluator: samples performance + activity metrics over a run and emits\n// a JSON report to logs/eval-<timestamp>.json.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport type { World } from '../engine/World.js';\nimport type { EvalReport } from '../types/index.js';\nimport { Logger } from '../reliability/Logger.js';\nconst log = Logger.for('evaluator');\nconst __dirname = path.dirname(fileURLToPath(import.meta.url));\nconst LOG_DIR = path.resolve(__dirname, '../../logs');\nexport interface EvalCounters { events: number; collisions: number; messages: number; moved: number; soulActions: number; soulActionsSucceeded: number; perceivedEvents: number; }\nexport class WorldEvaluator {\n  private readonly tickSamples: number[] = [];\n  private readonly counters: EvalCounters = { events: 0, collisions: 0, messages: 0, moved: 0, soulActions: 0, soulActionsSucceeded: 0, perceivedEvents: 0 };\n  recordTick(ms: number): void { this.tickSamples.push(ms); }\n  bump(field: keyof EvalCounters, by = 1): void { this.counters[field] += by; }\n  buildReport(world: World): EvalReport {\n    const samples = [...this.tickSamples].sort((a, b) => a - b);\n    const avg = samples.length ? samples.reduce((a, b) => a + b, 0) / samples.length : 0;\n    const p95 = samples.length ? samples[Math.floor(samples.length * 0.95)] ?? avg : 0;\n    const p99 = samples.length ? samples[Math.floor(samples.length * 0.99)] ?? avg : 0;\n    const perTick = Math.max(1, world.tick);\n    const mem = process.memoryUsage().rss;\n    return {\n      generatedAt: new Date().toISOString(),\n      world: { name: world.config.name, tick: world.tick, worldTime: world.worldTime, entityCount: world.entities.size },\n      performance: { tickTimeAvgMs: round(avg), tickTimeP95Ms: round(p95), tickTimeP99Ms: round(p99), fps: avg > 0 ? round(1000 / avg) : 0, rssBytes: mem },\n      subsystems: world.systems.map((s) => ({ name: s.name, enabled: s.enabled })),\n      activity: { eventsPerTick: round(this.counters.events / perTick), collisionsPerTick: round(this.counters.collisions / perTick), messagesPerTick: round(this.counters.messages / perTick), movedEntitiesPerTick: round(this.counters.moved / perTick) },\n      soulInteraction: { actionSuccessRate: this.counters.soulActions === 0 ? 1 : round(this.counters.soulActionsSucceeded / this.counters.soulActions), perceivedEvents: this.counters.perceivedEvents, connectedSouls: world.queryByType('soul-proxy').length },\n    };\n  }\n  flush(world: World): string {\n    fs.mkdirSync(LOG_DIR, { recursive: true });\n    const report = this.buildReport(world);\n    const stamp = new Date().toISOString().replace(/[:.]/g, '-');\n    const file = path.join(LOG_DIR, `eval-${stamp}.json`);\n    fs.writeFileSync(file, JSON.stringify(report, null, 2), 'utf8');\n    console.log('--- Seed Evaluation Report ---');\n    console.log(`world:        ${report.world.name} (tick=${report.world.tick}, entities=${report.world.entityCount})`);\n    console.log(`tick ms:      avg=${report.performance.tickTimeAvgMs} p95=${report.performance.tickTimeP95Ms} p99=${report.performance.tickTimeP99Ms}`);\n    console.log(`fps:          ${report.performance.fps}`);\n    console.log(`rss:          ${(report.performance.rssBytes / 1024 / 1024).toFixed(2)} MB`);\n    console.log(`activity/tick: events=${report.activity.eventsPerTick} collisions=${report.activity.collisionsPerTick} messages=${report.activity.messagesPerTick} moved=${report.activity.movedEntitiesPerTick}`);\n    console.log(`soul:         successRate=${report.soulInteraction.actionSuccessRate} connected=${report.soulInteraction.connectedSouls}`);\n    console.log(`report:       ${file}`);\n    log.info({ file }, 'evaluation report written');\n    return file;\n  }\n}\nfunction round(n: number): number { return Math.round(n * 1000) / 1000; }\n"

F['src/evaluator/runEval.ts'] = "// npm run eval entrypoint: builds a tiny synthetic world, runs a fixed number of\n// ticks while timing each, then writes logs/eval-<timestamp>.json.\nimport { WorldBuilder, EntityFactory, PhysicsConfig, AcousticPropagation } from '../sdk/index.js';\nimport { Message } from '../communication/Message.js';\nimport type { GameObject } from '../entity/Entity.js';\nimport { WorldEvaluator } from './WorldEvaluator.js';\nimport { Logger } from '../reliability/Logger.js';\nconst log = Logger.for('eval-main');\nfunction main(): void {\n  const world = new WorldBuilder('eval-world')\n    .setConfig({ tickRate: 60 })\n    .usePhysics(PhysicsConfig.builder().gravity(9.8).restitution(0.6).build())\n    .addEntity(EntityFactory.staticBox('ground', { x: 0, y: -0.5, z: 0 }, { x: 20, y: 0.5, z: 20 }))\n    .addEntity(EntityFactory.dynamicBox({ name: 'box-a', position: { x: -2, y: 5, z: 0 }, mass: 1, material: 'wood' }))\n    .addEntity(EntityFactory.dynamicBox({ name: 'box-b', position: { x: 2, y: 7, z: 0 }, mass: 3, material: 'metal' }))\n    .addEntity(EntityFactory.soulProxy({ soulId: 'eval_vex', name: 'Vex', element: 'wind', position: { x: -1, y: 1, z: 0 } }))\n    .build();\n  const evaluator = new WorldEvaluator();\n  world.events.on('physics.collision', () => evaluator.bump('collisions'));\n  world.events.on('world.tick', () => evaluator.bump('events'));\n  const TICKS = 120; const dt = 1 / 60;\n  for (let i = 0; i < TICKS; i++) { const t0 = performance.now(); world.step(dt); evaluator.recordTick(performance.now() - t0); }\n  const acoustic = new AcousticPropagation({ maxRadius: 30 });\n  const vex = world.getEntity('soul_eval_vex')!;\n  const nova = EntityFactory.soulProxy({ soulId: 'eval_nova', name: 'Nova', element: 'fire', position: { x: 5, y: 1, z: 0 } });\n  world.addEntity(nova);\n  const received = acoustic.transmit(\n    new Message({ content: 'hello from Vex', sourceId: vex.id, position: vex.position.toObject(), medium: 'acoustic', intensity: 1 }),\n    vex as never,\n    { entities: world.bodies() as unknown as GameObject[], byId: (id) => world.getEntity(id) as never },\n  );\n  evaluator.bump('messages', received.length);\n  evaluator.flush(world);\n  log.info({ received: received.length }, 'eval complete');\n}\nmain();\n"

for rel,content in F.items():
    full=os.path.join(BASE,rel)
    os.makedirs(os.path.dirname(full),exist_ok=True)
    with open(full,'w',encoding='utf-8',newline='\n') as f: f.write(content)
    print(f'WROTE {rel}')
print('DONE p4')
